  var BOX = { cactus_small: [17, [[0,7,5,27],[4,0,6,34],[10,4,7,14]]], cactus_large: [25, [[0,12,7,38],[8,0,7,49],[13,10,10,38]]], bird: [46, [[15,15,16,5],[18,21,24,6],[2,14,4,3],[6,10,4,7],[10,8,6,9]]] };
  var PAD = 2;
  var P = null, G = null, obs = [], over = false, gx = null, clouds = [];
  for (var i = 0; i < frame.length; i++) {
    var d = frame[i];
    if (d.k === 'text') { if (/game\s*over/i.test(d.t || '')) over = true; continue; }
    if (d.k === 'rect') { if (d.w > 0 && d.h > 0 && d.w < 300 && d.h < 100) obs.push({ kind: 'unknown', x: d.x, y: d.y, w: d.w, h: d.h }); continue; }
    if (d.k !== 'img') continue;
    var m = /:([^,]*),([^,]*),([^,]*),([^,]*)$/.exec(d.s || '');
    var sx = m ? +m[1] : NaN, sy = m ? +m[2] : NaN;
    if (sy >= 50 || d.w >= 300) { if (d.w >= 300) { if (G === null) G = d.y + d.h + 1; if (gx === null) gx = d.x; } continue; }
    if (d.w === 10 && d.h === 13 && d.y < 40) continue; // score digits
    if (sx >= 645 && sx < 655 && d.w <= 10) continue; // night-mode stars
    if (sy === 15 && sx >= 655) { over = true; continue; }
    if (sx === 2 && sy === 2) { over = true; continue; }
    if (sx >= 848 && sy <= 2 && d.h >= 20) {
      var st = (sx >= 1112 || d.w > 50) ? 'duck' : sx === 1068 ? 'crashed' : sx === 848 ? 'jump' : 'run';
      if (st === 'crashed') over = true;
      P = { x: d.x, y: d.y, w: d.w, h: d.h, state: st };
      continue;
    }
    if (sx === 86 && sy === 2) { clouds.push({ x: d.x, y: d.y }); continue; }
    if (sy === 2 && sx >= 484 && sx < 655) continue; // moon
    var kind = sy !== 2 ? 'unknown' : (sx >= 228 && sx < 332) ? 'cactus_small' : (sx >= 332 && sx < 484) ? 'cactus_large' : (sx >= 134 && sx < 228) ? 'bird' : 'unknown';
