  }
  if (G === null) { G = P ? P.y + P.h : 0; for (var j = 0; j < obs.length; j++) G = Math.max(G, obs[j].y + obs[j].h); }
  if (over) { memory.hist = []; memory.ok = null; memory.wantF = 0; }
  // game frames since the previous decision: clouds drift exactly 1 px per frame
  var frames = null, prevC = memory.clouds || [];
  if (clouds.length && prevC.length) {
    var ds = [];
    for (var c = 0; c < clouds.length; c++) {
      var best = 99;
      for (var q = 0; q < prevC.length; q++) { var cd = prevC[q].x - clouds[c].x; if (prevC[q].y === clouds[c].y && cd >= 0 && cd < best) best = cd; }
      if (best <= 12) ds.push(best);
    }
    if (ds.length) { ds.sort(function (a, b) { return a - b; }); frames = ds[ds.length >> 1]; }
  }
  memory.clouds = clouds;
  // ground scroll since the previous decision (the two ground strips are 600 px apart)
  var dg = (gx !== null && typeof memory.gx === 'number') ? ((memory.gx - gx) % 600 + 600) % 600 : null;
  memory.gx = gx;
  var hist = memory.hist || (memory.hist = []);
  var ppf = typeof memory.ppf === 'number' ? memory.ppf : 6.4;
  if (!over && dg !== null) {
    if (frames === null && dg > 0) frames = Math.max(1, Math.round(dg / ppf));
    if (frames > 0 && dg / frames >= 4.5 && dg / frames <= 14) { hist.push([dg, frames]); if (hist.length > 6) hist.shift(); }
    if (frames !== null) memory.fpd = typeof memory.fpd === 'number' ? memory.fpd * 0.7 + Math.min(frames, 6) * 0.3 : 2.6;
  }
  if (hist.length) { var sg = 0, sf = 0; for (var h = 0; h < hist.length; h++) { sg += hist[h][0]; sf += hist[h][1]; } ppf = sg / sf; }
  memory.ppf = ppf;
  var fpd = typeof memory.fpd === 'number' ? Math.max(1, memory.fpd) : 2.6;
  // player phase from the altitude change
  var alt = P ? Math.round(G - P.y - P.h) : 0, pst = P ? P.state : 'run';
  var prevAlt = typeof memory.alt === 'number' ? memory.alt : 0, phase;
  if (alt <= 1 && pst !== 'jump') phase = 'ground';
  else if (alt > prevAlt) phase = 'rising';
  else if (alt < prevAlt) phase = 'falling';
  else if (alt <= 1 || frames === 0 || alt < 80) phase = memory.phase === 'falling' ? 'falling' : 'rising';
  else phase = 'falling';
  memory.alt = alt; memory.phase = phase;
  var ground = phase === 'ground';
  if (!ground) { memory.ok = null; memory.wantF = 0; }
  // obstacles that can still hit the dino
  var pl = P ? P.x : 0, pr = pl + 44;
  var live = obs.filter(function (o) { return o.x + o.w > pl && (o.kind === 'bird' || G - o.y - o.h < 60); }).sort(function (a, b) { return a.x - b.x; });
  var prevB = memory.birds || [], birds = [];
  live.forEach(function (o) {
    o.v = ppf;
    if (o.kind !== 'bird') return;
    birds.push({ x: o.x, y: o.y });
    for (var q = 0; q < prevB.length; q++) if (frames > 0 && prevB[q].y === o.y) { var bv = (prevB[q].x - o.x) / frames; if (bv > ppf - 2.5 && bv < ppf + 2.5) o.v = bv; }
  });
  memory.birds = birds;
  var nLo = Math.max(1, Math.ceil((lag - 12) / 16)), nHi = Math.max(1, Math.ceil((lag + 12) / 16));
  function boxes(o) {
    var t = BOX[o.kind];
    if (!t) return [[0, 0, o.w, o.h]];
    var b = t[1].map(function (a) { return a.slice(); });
    if (o.kind !== 'bird' && Math.round(o.w / t[0]) > 1) { b[1][2] = o.w - b[0][2] - b[2][2]; b[2][0] = o.w - b[2][2]; }
    return b;
  }
  // does the obstacle, rx px right of the dino's x, touch the dino at altitude a?
  function hit(o, bx, rx, a) {
    var ty = G - 46 - a;
    if (rx + o.w - 1 + PAD <= 1 || rx + 1 - PAD >= 43 || o.y + o.h - 1 <= ty || o.y + 1 - PAD >= ty + 45) return false;
    for (var t = 0; t < DINO.length; t++) {
      var T = DINO[t];
      for (var j = 0; j < bx.length; j++) {
        var b = bx[j], x2 = rx + 1 + b[0] - PAD, y2 = o.y + 1 + b[1] - PAD;
        if (1 + T[0] < x2 + b[2] + 2 * PAD && 1 + T[0] + T[2] > x2 && ty + T[1] < y2 + b[3] + PAD && ty + T[1] + T[3] > y2) return true;
      }
    }
    return false;
  }
  // is a jump pressed d frames from now clear of the obstacle, for every lag in the band?
  function clear(o, bx, d, n0, n1) {
    var rx0 = o.x - pl;
    for (var n = n0; n <= n1; n++) {
      var s = n + d, f, k;
      if (rx0 - o.v * (s + LAND - 1) + o.w > 0) return false;
      for (f = 1; f < s; f++) if (hit(o, bx, rx0 - o.v * f, 0)) return false;
      for (k = 1; k < LAND; k++) if (hit(o, bx, rx0 - o.v * (s + k - 1), ALT[k])) return false;
    }
    return true;
  }
  function scan(o, n0, n1) {
    var bx = boxes(o), lim = Math.min(200, Math.ceil(Math.max(0, o.x - pl) / o.v) + 2), lo = -1, hi = -1;
    for (var d = 0; d <= lim; d++) {
      if (clear(o, bx, d, n0, n1)) { if (lo < 0) lo = d; hi = d; }
      else if (lo >= 0) break;
    }
    return lo < 0 ? null : [lo, hi];
  }
  function timing(a, b) {
    if (a.duckable) return 'n/a';
    var W = scan(a.o, nLo, nHi);
    if (!W) {
      var nm = Math.round((nLo + nHi) / 2);
      W = scan(a.o, nm, nm);
      if (!W) return (a.o.x - pr) / a.o.v <= nHi + 6 ? 'late' : 'early';
    }
    if (W[0] > 0) return 'early';
    var best = Math.floor(W[1] / 2);
    if (b && !b.duckable) { var WB = scan(b.o, nLo, nHi); if (WB) best = Math.min(best, WB[1] - LAND - Math.ceil(fpd)); }
    return (best <= fpd / 2 || W[1] < fpd) ? 'ok' : 'early';
  }
  var ahead = live.slice(0, 3).map(function (o) {
    var bottom = Math.round(G - o.y - o.h), top = Math.round(G - o.y), ov = o.v / 16, dx = o.x - pr - ov * lag;
    var bird = o.kind === 'bird';
    return { o: o, kind: o.kind, dx: Math.round(dx), top: top, bottom: bottom, overhead: bird && bottom >= 45, duckable: bird && bottom >= 15 && bottom < 45, impactMs: Math.round((dx + 5) / ov), passMs: Math.round((dx + o.w + 41) / ov) };
  });
  var cands = ahead.filter(function (a) { return !a.overhead && (!ground || a.passMs > 0); });
  var A = cands[0] || null, B = cands[1] || null, jt = null;
  if (A) jt = (ground && !over) ? timing(A, B) : 'n/a';
  if (A && ground && !A.duckable) {
    var ok = memory.ok, same = ok && ok.kind === A.kind && ok.w === A.o.w && A.o.x <= ok.x + 1 && A.o.x >= ok.x - 150;
    if (jt === 'early' && same) jt = 'ok';
    if (jt === 'ok' || jt === 'late') { memory.ok = { kind: A.kind, w: A.o.w, x: A.o.x }; memory.wantF = (memory.wantF || 0) + (frames || 0); }
    else { memory.ok = null; memory.wantF = 0; }
  }
  var jumpReady = pst !== 'duck';
  if ((memory.wantF || 0) >= nHi + 6) { jumpReady = false; memory.wantF = 0; }
  var speed = Math.min(0.85, Math.max(0.31, ppf / 16));
  return {
    over: over,
    player: P ? { alt: alt, phase: phase } : null,
    jumpReady: jumpReady,
    speed: Math.round(speed * 1000) / 1000,
    threat: A ? { kind: A.kind, dx: A.dx, top: A.top, bottom: A.bottom, impactMs: A.impactMs, passMs: A.passMs, duckable: A.duckable, jumpTiming: jt } : null,
    obstacles: ahead.map(function (a) { return { kind: a.kind, dx: a.dx, top: a.top, bottom: a.bottom, overhead: a.overhead }; })
  };
}

teacher:
function teach(state) {
  if (!state) return 'NOOP';
  // 1. Game over -> JUMP restarts
  if (state.over === true) return 'JUMP';
  var p = state.player || {};
  // 2. Rising -> keep JUMP held (an early release cuts the jump into a low hop)
  if (p.phase === 'rising') return 'JUMP';
  // 3. Falling -> release so the next jump is a fresh press
  if (p.phase === 'falling') return 'NOOP';
  var t = state.threat;
  // 4. No threat -> NOOP
  if (t === null || t === undefined) return 'NOOP';
  // 5. Duckable bird close (or passing) -> DUCK
  if (t.duckable === true && typeof t.impactMs === 'number' && t.impactMs <= 250) return 'DUCK';
  // 6. Jump now (or as soon as possible) unless the key must be released first
  if (t.jumpTiming === 'ok' || t.jumpTiming === 'late') return state.jumpReady === false ? 'NOOP' : 'JUMP';
  // 7. Early / n/a -> wait
  return 'NOOP';
}
